/* wkclip.c — implementation of wkclip.h over the wit-bindgen C bindings.
 *
 * The bindings (gen/wkclipboard.h + gen/wkclipboard.c +
 * gen/wkclipboard_component_type.o) are regenerated by each consumer's
 * build.sh:
 *
 *     wit-bindgen c --world wkclipboard ../clipboard-compat/wit \
 *         --out-dir ../clipboard-compat/gen
 *
 * There is no state here at all — no `open`, no handle, unlike wkmidi's input
 * resource. wk:clipboard is two free functions over a value the host has
 * already published, which is what lets a toolkit call wkclip_get() from
 * inside a synchronous paste handler.
 *
 * The one thing worth knowing: the string that comes back lives in
 * canonical-ABI-allocated guest memory owned by the bindings, and it is NOT
 * NUL-terminated. We copy it into a malloc'd buffer with room for a
 * terminator and free the original immediately, so callers get something they
 * can hand to ordinary C string code and free() themselves.
 */
#include "wkclip.h"

#include <stdlib.h>
#include <string.h>

#include "gen/wkclipboard.h"

int wkclip_get(char **out_text, uint64_t *out_seq)
{
    if (!out_text)
        return 0;

    wk_clipboard_clipboard_snapshot_t snap;
    if (!wk_clipboard_clipboard_get(&snap))
        return 0; /* not wired, token denies read, or no host clipboard */

    char *copy = (char *)malloc(snap.text.len + 1);
    if (!copy) {
        wk_clipboard_clipboard_snapshot_free(&snap);
        return 0;
    }
    if (snap.text.len)
        memcpy(copy, snap.text.ptr, snap.text.len);
    copy[snap.text.len] = '\0';

    if (out_seq)
        *out_seq = snap.seq;
    *out_text = copy;

    /* Frees the list behind snap.text; the bytes are already copied out. */
    wk_clipboard_clipboard_snapshot_free(&snap);
    return 1;
}

void wkclip_set(const char *text)
{
    if (!text)
        return;
    /* _set (not _dup): the canonical ABI copies the bytes out of guest memory
     * during the call, so borrowing the caller's buffer is correct and saves
     * an allocation on a path a text editor hits on every Ctrl+C. */
    wkclipboard_string_t s;
    wkclipboard_string_set(&s, text);
    wk_clipboard_clipboard_set(&s);
}
